function validate([matrix, numSelect]) {
  if (!Array.isArray(matrix) || matrix.length < 1 || matrix.length > 12) return 'matrix needs 1 to 12 rows.';
  const n = matrix[0].length;
  if (n < 1 || n > 12) return 'matrix needs 1 to 12 columns.';
  if (matrix.some(row => row.length !== n)) return 'Every row must have the same length.';
  if (matrix.some(row => row.some(cell => cell !== 0 && cell !== 1))) return 'Every cell is 0 or 1.';
  if (!Number.isInteger(numSelect) || numSelect < 1 || numSelect > n) return 'numSelect is between 1 and the number of columns.';
  return null;
}

