function maximumRows(matrix, numSelect) {
  const n = matrix[0].length;
  const rowMasks = [];
  for (const row of matrix) {
    let mask = 0;
    for (let j = 0; j < n; j++) {
      if (row[j] === 1) {
        mask |= 1 << j;
      }
    }
    rowMasks.push(mask);
  }

  let best = 0;
  for (let selected = 0; selected < (1 << n); selected++) {
    let bits = 0;
    for (let rest = selected; rest > 0; rest &= rest - 1) {
      bits++;
    }
    if (bits !== numSelect) {
      continue;
    }
    let covered = 0;
    for (const mask of rowMasks) {
      if ((mask & selected) === mask) {
        covered++;
      }
    }
    best = Math.max(best, covered);
  }
  return best;
}

