function maximumRows(matrix, numSelect) {
  const n = matrix[0].length;
  const chosen = new Array(n).fill(false);
  let best = 0;
  const pick = (col, left) => {
    if (left === 0) {
      const covered = matrix.filter(row => row.every((cell, j) => cell === 0 || chosen[j])).length;
      best = Math.max(best, covered);
      return;
    }
    if (col === n) return;
    chosen[col] = true;
    pick(col + 1, left - 1);
    chosen[col] = false;
    pick(col + 1, left);
  };
  pick(0, numSelect);
  return best;
}

