function generate(rand, size) {
  const m = size === 'large' ? 12 : 1 + Math.floor(rand() * 5);
  const n = size === 'large' ? 12 : 1 + Math.floor(rand() * 5);
  const density = rand() * 0.7;
  const matrix = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  const numSelect = 1 + Math.floor(rand() * n);
  return [matrix, numSelect];
}
